-- 0120_form_fillers.sql
-- The ServiceOntario form filler, checked against the official PDFs (docs/changes/2026-10-23-form-fillers.md). The draft
-- mappings of 0047 put CarmaCars' whole one-line address in the 45-character street box (the unit, city and postal code
-- never reached their boxes, and the postal code was cut in half), named an individual "OLIVIA MARGARET TREMBLAY" where
-- the form asks "Last Name, First Name and Middle Initial", used an individual's driver's licence and birth date for a
-- corporation that owns the car, filled Section 1 of the Supplementary Application for every method (it is only for
-- plates owned by someone other than the vehicle owner) and drew the owner's signature in sections the owner does not
-- sign, left the VIN out of the insurance certificate (SR-LV-006 section 7), and printed "+14165550142" for a phone.
--
-- 1. Phone numbers stored with their country code (+1 and ten digits) are formatted like ten-digit ones.
-- 2. The registry context (0022, 0047) gains what the forms ask for in their own shape: the CarmaCars address split into
--    street, unit, city, province and postal code; the owner's street number and street name apart; the registry name
--    ("TREMBLAY, OLIVIA M"); and, by onboarding method, who is the vehicle's registrant (SR-LV-006 section 1: the owner's
--    corporation under a Lease, the owner under Co-Registrant, the lessor or CarmaCars under a Transfer), who owns the
--    plates when that is someone else (SR-LV-012 section 1: CarmaCars, the lessee), whether two registrants share the
--    permit (SR-LV-012 section 2), and whether the owner is the one who signs the application.
-- 3. The sources of Admin > Settings > Forms list them.
-- 4. The mapping of each official form is replaced where no Admin has saved one yet (the 0047 draft, untouched); a form
--    already in use for owners is filled again from it (a form signed or filed stays as it was).
-- 5. The agreements name the company; the signed copy of a document is the whole document.
-- 6. The publisher's PDFs, unchanged: only the empty text boxes are filled, everything else is done by hand at the
--    counter and signed in ink (the owner's rule of October 23, 2026).
-- 7. The guides say so.

-- ---------------------------------------------------------------- 1. phone numbers with their country code
create or replace function app.apply_transform(p_value text, p_transform text) returns text
language sql immutable as $$
  select case
    when p_value is null or btrim(p_value) = '' then null
    when p_transform is null or p_transform = '' then p_value
    when p_transform = 'upper' then upper(p_value)
    when p_transform = 'lower' then lower(p_value)
    when p_transform = 'postal' then
      case when upper(regexp_replace(p_value, '\s', '', 'g')) ~ '^[A-Z][0-9][A-Z][0-9][A-Z][0-9]$'
           then substr(upper(regexp_replace(p_value, '\s', '', 'g')), 1, 3) || ' ' || substr(upper(regexp_replace(p_value, '\s', '', 'g')), 4, 3)
           else upper(p_value) end
    when p_transform = 'phone' then
      case when regexp_replace(p_value, '\D', '', 'g') ~ '^1?\d{10}$'
           then regexp_replace(right(regexp_replace(p_value, '\D', '', 'g'), 10), '^(\d{3})(\d{3})(\d{4})$', '(\1) \2-\3')
           else p_value end
    when p_transform = 'yesno' then case when lower(p_value) in ('true', 't', 'yes', 'y', '1') then 'Yes' else 'No' end
    when p_transform = 'money' then '$' || btrim(to_char(p_value::numeric / 100, 'FM999,999,990.00'))
    when p_transform like 'date:%' then to_char(p_value::date, substr(p_transform, 6))
    else p_value end
$$;

-- ---------------------------------------------------------------- 2. the context in the forms' own shape
-- "2967 Dundas St W, Unit 208B, Toronto, ON M6P 1Z2" as its parts: the street line, the unit (without its word), the
-- city, the province and the postal code. A part that is not there is null.
create or replace function app.split_ca_address(p text) returns jsonb
language plpgsql immutable as $$
declare
  parts text[] := array(select btrim(x) from unnest(string_to_array(coalesce(p, ''), ',')) x where btrim(x) <> '');
  v_postal text;
  v_prov text;
  v_unit text;
  v_city text;
  v_line1 text;
  rest text[] := '{}';
  x text;
  m text[];
begin
  if cardinality(parts) = 0 then return jsonb_build_object('address_line1', null, 'unit', null, 'city', null, 'province', null, 'postal_code', null); end if;
  -- the last part: "ON M6P 1Z2", "ON", "M6P 1Z2" or "Ontario M6P1Z2"
  m := regexp_match(parts[cardinality(parts)], '^([A-Za-z .]*?)\s*([A-Za-z]\d[A-Za-z]\s?\d[A-Za-z]\d)$');
  if m is not null then
    v_postal := upper(m[2]); v_prov := nullif(btrim(m[1]), '');
    parts := parts[1:cardinality(parts) - 1];
  elsif parts[cardinality(parts)] ~* '^(ON|Ontario|QC|Quebec|BC|AB|MB|SK|NS|NB|NL|PE|YT|NT|NU)$' then
    v_prov := parts[cardinality(parts)]; parts := parts[1:cardinality(parts) - 1];
  end if;
  if v_prov is null and cardinality(parts) > 1 then
    m := regexp_match(parts[cardinality(parts)], '^(.*?)\s+(ON|QC|BC|AB|MB|SK|NS|NB|NL|PE|YT|NT|NU)$');
    if m is not null then v_prov := m[2]; parts[cardinality(parts)] := m[1]; end if;
  end if;
  if upper(v_prov) = 'ONTARIO' then v_prov := 'ON'; end if;
  foreach x in array parts loop
    if v_unit is null and x ~* '^\s*(unit|apt\.?|apartment|suite|ste\.?|#)\s*\S' then
      v_unit := btrim(regexp_replace(x, '^\s*(unit|apt\.?|apartment|suite|ste\.?|#)\s*', '', 'i'));
    else rest := rest || x; end if;
  end loop;
  v_line1 := rest[1];
  if cardinality(rest) > 1 then v_city := rest[cardinality(rest)]; end if;
  return jsonb_build_object('address_line1', v_line1, 'unit', v_unit, 'city', v_city, 'province', upper(v_prov),
    'postal_code', case when v_postal is null then null else substr(replace(v_postal, ' ', ''), 1, 3) || ' ' || substr(replace(v_postal, ' ', ''), 4, 3) end);
end $$;

-- "1204 Bay Street" as its number and its name (a line that does not start with a number keeps it all as the name)
create or replace function app.street_parts(p text) returns jsonb
language sql immutable as $$
  select case when btrim(coalesce(p, '')) ~ '^\d+[A-Za-z]?(-\d+)?\s+\S'
              then jsonb_build_object('number', (regexp_match(btrim(p), '^(\d+[A-Za-z]?(-\d+)?)\s+(.*)$'))[1], 'name', (regexp_match(btrim(p), '^(\d+[A-Za-z]?(-\d+)?)\s+(.*)$'))[3])
              else jsonb_build_object('number', null, 'name', nullif(btrim(coalesce(p, '')), '')) end
$$;

-- The registry's own order for a person: "Last Name, First Name and Middle Initial" (TREMBLAY, OLIVIA M).
create or replace function app.registry_person_name(p_last text, p_first text, p_middle text, p_legal text) returns text
language sql immutable as $$
  select case when nullif(btrim(coalesce(p_last, '')), '') is not null and nullif(btrim(coalesce(p_first, '')), '') is not null
              then upper(btrim(p_last) || ', ' || btrim(p_first) || coalesce(' ' || left(nullif(btrim(coalesce(p_middle, '')), ''), 1), ''))
              else upper(nullif(btrim(coalesce(p_legal, '')), '')) end
$$;

alter function app.registry_context(uuid) rename to registry_context_0047;
create or replace function app.registry_context(p_vehicle uuid) returns jsonb
language plpgsql stable security definer set search_path = public, app as $$
declare
  c jsonb := app.registry_context_0047(p_vehicle);
  o jsonb;
  reg jsonb;
  corp jsonb;
  co jsonb;
  st jsonb;
  m text;
  v_leased boolean;
  vr jsonb;
  po jsonb;
  v_corp_signer text;
begin
  if c is null then return null; end if;
  o := c -> 'owner'; corp := c -> 'corporation'; m := c #>> '{method,code}';
  v_leased := c #>> '{title,status}' = 'leased';
  -- CarmaCars, the company: its one-line address in its parts
  co := app.split_ca_address(c #>> '{registrant,address}');
  st := app.street_parts(co ->> 'address_line1');
  reg := (c -> 'registrant') || co || jsonb_build_object('street_number', st ->> 'number', 'street_name', st ->> 'name',
           'registry_name', upper(c #>> '{registrant,legal_name}'));
  -- the owner: the street line in two, the registry name
  st := app.street_parts(o ->> 'address_line1');
  o := o || jsonb_build_object('street_number', st ->> 'number', 'street_name', st ->> 'name',
         'registry_name', app.registry_person_name(o ->> 'last_name', o ->> 'first_name', o ->> 'middle_name', o ->> 'legal_name'));
  v_corp_signer := coalesce(nullif(btrim(corp ->> 'signing_officer_name'), ''), o ->> 'legal_name');
  corp := corp || jsonb_build_object('signer_name', v_corp_signer, 'registry_name', upper(nullif(btrim(coalesce(corp ->> 'name', '')), '')));
  -- who is the vehicle's registrant on SR-LV-006 section 1, and who signs the application
  vr := case
    when m in ('lease_existing_corporation', 'lease_new_owner_corporation') then jsonb_build_object(
      'name', upper(coalesce(nullif(btrim(corp ->> 'name'), ''), o ->> 'legal_name')), 'rin', corp ->> 'rin', 'date_of_birth', null,
      'address_line1', o ->> 'address_line1', 'unit', o ->> 'unit', 'city', o ->> 'city', 'province', o ->> 'province', 'postal_code', o ->> 'postal_code',
      'signer_name', v_corp_signer, 'owner_signs', true, 'is_individual', false)
    when m = 'co_registrant' then jsonb_build_object(
      'name', o ->> 'registry_name', 'rin', o ->> 'licence_number', 'date_of_birth', o ->> 'date_of_birth',
      'address_line1', o ->> 'address_line1', 'unit', o ->> 'unit', 'city', o ->> 'city', 'province', o ->> 'province', 'postal_code', o ->> 'postal_code',
      'signer_name', o ->> 'legal_name', 'owner_signs', true, 'is_individual', true)
    when m = 'transfer' and v_leased then jsonb_build_object(
      -- the lessor keeps the vehicle; its RIN and address are on the lease and the permit, written at the counter
      'name', upper(nullif(btrim(coalesce(c #>> '{lender,name}', '')), '')), 'rin', null, 'date_of_birth', null,
      'address_line1', null, 'unit', null, 'city', null, 'province', null, 'postal_code', null,
      'signer_name', reg ->> 'signing_officer_name', 'owner_signs', false, 'is_individual', false)
    when m = 'transfer' then jsonb_build_object(
      'name', reg ->> 'registry_name', 'rin', reg ->> 'rin', 'date_of_birth', null,
      'address_line1', reg ->> 'address_line1', 'unit', reg ->> 'unit', 'city', reg ->> 'city', 'province', reg ->> 'province', 'postal_code', reg ->> 'postal_code',
      'signer_name', reg ->> 'signing_officer_name', 'owner_signs', false, 'is_individual', false)
    else jsonb_build_object('name', null, 'owner_signs', false, 'is_individual', false) end;
  -- the plates are CarmaCars' (the lessee) under a Lease, and under a Transfer of a leased car
  po := case when m in ('lease_existing_corporation', 'lease_new_owner_corporation') or (m = 'transfer' and v_leased)
             then jsonb_build_object('name', reg ->> 'registry_name', 'rin', reg ->> 'rin', 'address_line1', reg ->> 'address_line1', 'unit', reg ->> 'unit',
                    'city', reg ->> 'city', 'province', reg ->> 'province', 'postal_code', reg ->> 'postal_code', 'signer_name', reg ->> 'signing_officer_name')
             else '{}'::jsonb end;
  return c || jsonb_build_object('owner', o, 'registrant', reg, 'corporation', corp, 'vehicle_registrant', vr, 'plate_owner', po,
    'method', (c -> 'method') || jsonb_build_object('plates_other', po <> '{}'::jsonb, 'two_registrants', m = 'co_registrant',
                                                    'owner_signs_application', coalesce((vr ->> 'owner_signs')::boolean, false)));
end $$;
revoke all on function app.registry_context(uuid) from public, anon, authenticated;
grant execute on function app.registry_context(uuid) to service_role;
revoke all on function app.registry_context_0047(uuid) from public, anon, authenticated;
grant execute on function app.registry_context_0047(uuid) to service_role;

-- ---------------------------------------------------------------- 3. the sources Admin > Settings > Forms offers
