    jsonb_build_object('path', 'owner.registry_name', 'label', 'Owner: name as the registry writes it (LAST, FIRST M)', 'section', 'Owner'),
    jsonb_build_object('path', 'owner.street_number', 'label', 'Owner: street number only', 'section', 'Owner'),
    jsonb_build_object('path', 'owner.street_name', 'label', 'Owner: street name only', 'section', 'Owner'),
    jsonb_build_object('path', 'corporation.registry_name', 'label', 'Corporation: name in capitals', 'section', 'Corporation'),
    jsonb_build_object('path', 'corporation.signer_name', 'label', 'Corporation: who signs for it (signing officer, else the owner)', 'section', 'Corporation'),
    jsonb_build_object('path', 'registrant.address_line1', 'label', 'CarmaCars company: street line', 'section', 'Registrant'),
    jsonb_build_object('path', 'registrant.unit', 'label', 'CarmaCars company: unit', 'section', 'Registrant'),
    jsonb_build_object('path', 'registrant.city', 'label', 'CarmaCars company: city', 'section', 'Registrant'),
    jsonb_build_object('path', 'registrant.province', 'label', 'CarmaCars company: province', 'section', 'Registrant'),
    jsonb_build_object('path', 'registrant.postal_code', 'label', 'CarmaCars company: postal code', 'section', 'Registrant'),
    jsonb_build_object('path', 'registrant.registry_name', 'label', 'CarmaCars company: legal name in capitals', 'section', 'Registrant'),
    jsonb_build_object('path', 'vehicle_registrant.name', 'label', 'Vehicle registrant (SR-LV-006 section 1): name', 'section', 'Vehicle registrant'),
    jsonb_build_object('path', 'vehicle_registrant.rin', 'label', 'Vehicle registrant: RIN or driver''s licence number', 'section', 'Vehicle registrant'),
    jsonb_build_object('path', 'vehicle_registrant.date_of_birth', 'label', 'Vehicle registrant: date of birth (a person only)', 'section', 'Vehicle registrant'),
    jsonb_build_object('path', 'vehicle_registrant.address_line1', 'label', 'Vehicle registrant: street line', 'section', 'Vehicle registrant'),
    jsonb_build_object('path', 'vehicle_registrant.unit', 'label', 'Vehicle registrant: unit', 'section', 'Vehicle registrant'),
    jsonb_build_object('path', 'vehicle_registrant.city', 'label', 'Vehicle registrant: city', 'section', 'Vehicle registrant'),
    jsonb_build_object('path', 'vehicle_registrant.postal_code', 'label', 'Vehicle registrant: postal code', 'section', 'Vehicle registrant'),
    jsonb_build_object('path', 'vehicle_registrant.signer_name', 'label', 'Vehicle registrant: who signs the application', 'section', 'Vehicle registrant'),
    jsonb_build_object('path', 'vehicle_registrant.owner_signs', 'label', 'The owner signs the application (yes or no)', 'section', 'Vehicle registrant'),
    jsonb_build_object('path', 'plate_owner.name', 'label', 'Plate owner, when not the vehicle registrant: name', 'section', 'Plate owner'),
    jsonb_build_object('path', 'plate_owner.rin', 'label', 'Plate owner: RIN', 'section', 'Plate owner'),
    jsonb_build_object('path', 'plate_owner.address_line1', 'label', 'Plate owner: street line', 'section', 'Plate owner'),
    jsonb_build_object('path', 'plate_owner.unit', 'label', 'Plate owner: unit', 'section', 'Plate owner'),
    jsonb_build_object('path', 'plate_owner.city', 'label', 'Plate owner: city', 'section', 'Plate owner'),
    jsonb_build_object('path', 'plate_owner.postal_code', 'label', 'Plate owner: postal code', 'section', 'Plate owner'),
    jsonb_build_object('path', 'plate_owner.signer_name', 'label', 'Plate owner: who certifies', 'section', 'Plate owner'),
    jsonb_build_object('path', 'method.plates_other', 'label', 'The plates belong to someone other than the vehicle registrant (yes or no)', 'section', 'Method'),
    jsonb_build_object('path', 'method.two_registrants', 'label', 'Two registrants share the permit (yes or no)', 'section', 'Method'),
    jsonb_build_object('path', 'method.owner_signs_application', 'label', 'The owner signs the application (yes or no)', 'section', 'Method'))
$$;
grant execute on function app.registry_sources() to service_role, authenticated;

-- ---------------------------------------------------------------- 4. the mappings, where no Admin has saved one
-- A template the 0047 draft created (its SHA-256) and nobody mapped since gets the checked mapping, notes and field list.
create or replace function app.official_form_remap(p_code text, p_sha256 text, p_fields jsonb, p_map jsonb, p_notes text) returns integer
language plpgsql security definer set search_path = public, app as $$
declare
  t pdf_templates;
  g record;
  n integer := 0;
begin
  select * into t from pdf_templates where form_code = p_code and sha256 = p_sha256 and mapped_by is null for update;
  if t.id is null then return 0; end if;
  update pdf_templates set field_map = p_map, field_names = p_fields, notes = p_notes, mapped_at = now() where id = t.id;
  if t.verified and t.is_current then
    for g in select f.vehicle_id from government_form_fills f where f.form_code = p_code and f.superseded_at is null and f.status not in ('signed', 'filed') loop
      perform app.fill_government_form(g.vehicle_id, p_code, null);
      n := n + 1;
    end loop;
  end if;
  return n;
end $$;
revoke all on function app.official_form_remap(text, text, jsonb, jsonb, text) from public, anon, authenticated;
grant execute on function app.official_form_remap(text, text, jsonb, jsonb, text) to service_role;

-- ---------------------------------------------------------------- 5. the agreements name the company: "18122211 Canada Inc."
-- The owner's decision (October 23, 2026): "Agreements need to just say the numbered corp, no operating as." Every
-- agreement, its cover, its signature block and the pre-authorized debit agreement name the party by the company's legal
-- name alone (app.settings().company_legal_name); the countersignature reads "Signed electronically for 18122211 Canada
-- Inc., by <officer>, Director, under a standing authorization dated <date>." The facts of the owner agreements carry
-- the legal name.
create or replace function app.owner_payee_name() returns text
language sql stable security definer set search_path = public, app as $$
  select coalesce(nullif(btrim(s.company_legal_name), ''), s.company_trade_name) from app.settings() s
$$;

create or replace function app.corporate_signature_text() returns text
language sql stable security definer set search_path = public, app as $$
  select case when nullif(btrim(s.signing_officer_name), '') is not null
              then format('Signed electronically for %s, by %s, %s, under a standing authorization dated %s.',
                          coalesce(nullif(btrim(s.company_legal_name), ''), s.company_trade_name), s.signing_officer_name,
                          coalesce(nullif(btrim(s.signing_officer_title), ''), 'Director'),
                          to_char(coalesce(s.signing_officer_authorized_on, app.today()), 'FMMonth FMDD, YYYY'))
              else format('Signed electronically for %s.', coalesce(nullif(btrim(s.company_legal_name), ''), s.company_trade_name)) end
    from app.settings() s
$$;

create or replace function app.investment_countersign(p_admin uuid, p jsonb) returns jsonb
language plpgsql security definer set search_path = public, app as $$
declare
  s program_settings := app.settings();
  a investment_agreements;
  r sign_requests;
  v_sha text;
  v_rec uuid;
begin
  perform app.assert_admin(p_admin);
  if nullif(btrim(s.signing_officer_name), '') is null then
    raise exception 'Set the signing officer in Admin > Settings > Program settings first' using errcode = '23514';
  end if;
  if s.signing_officer_user_id is not null and s.signing_officer_user_id <> p_admin then
    raise exception 'Only the signing officer (%) countersigns an investment agreement', s.signing_officer_name using errcode = '42501';
  end if;
  select * into a from investment_agreements where id = coalesce(nullif(p ->> 'agreement_id', '')::uuid,
                     (select x.investment_agreement_id from sign_requests x where x.id = nullif(p ->> 'sign_request_id', '')::uuid)) for update;
  if a.id is null then raise exception 'Investment agreement not found' using errcode = 'P0002'; end if;
  if a.status <> 'signed' then raise exception 'The investor has not signed agreement % yet', a.agreement_number using errcode = '23514'; end if;
  if a.company_signed_at is not null then
    return jsonb_build_object('agreement_id', a.id, 'repeat', true, 'company_signed_at', a.company_signed_at);
  end if;
  select * into r from sign_requests where investment_agreement_id = a.id and status = 'signed' order by signed_at desc limit 1;
  v_sha := coalesce(r.document_sha256, (select d.sha256 from documents d where d.id = a.document_id));
  insert into signature_records (signature_request_id, signer_role, signer_user_id, signer_name, signer_title, signer_email, status, signed_at,
                                 method, typed_name, consent_text, document_sha256)
  values (coalesce(r.signature_request_id, a.signature_request_id), 'carmacars', p_admin, s.signing_officer_name, coalesce(nullif(btrim(s.signing_officer_title), ''), 'Director'),
          s.company_email, 'signed', now(), 'typed', s.signing_officer_name,
          format('Signed electronically for %s, by %s, %s.', coalesce(nullif(btrim(s.company_legal_name), ''), s.company_trade_name),
                 s.signing_officer_name, coalesce(nullif(btrim(s.signing_officer_title), ''), 'Director')),
          v_sha)
  returning id into v_rec;
  update investment_agreements set company_signed_at = now() where id = a.id;
  update signature_requests set status = 'completed', completed_at = now() where id = coalesce(r.signature_request_id, a.signature_request_id) and status <> 'completed';
  insert into audit_log (actor_user_id, action, entity_table, entity_id, after)
  values (p_admin, 'investment_countersign', 'investment_agreements', a.id::text,
          jsonb_build_object('agreement_number', a.agreement_number, 'signature_record_id', v_rec, 'signing_officer', s.signing_officer_name));
  return jsonb_build_object('agreement_id', a.id, 'signature_record_id', v_rec, 'company_signed_at', now(), 'sign_request_id', r.id);
end $$;

alter function app.owner_agreement_facts(uuid, uuid) rename to owner_agreement_facts_0053;
create or replace function app.owner_agreement_facts(p_owner uuid, p_by uuid) returns jsonb
language sql stable security definer set search_path = public, app as $$
  select f || jsonb_build_object('company', coalesce(f -> 'company', '{}'::jsonb) || jsonb_build_object('legal_name', (select s.company_legal_name from app.settings() s)))
    from app.owner_agreement_facts_0053(p_owner, p_by) f
$$;
revoke all on function app.owner_agreement_facts(uuid, uuid) from public, anon, authenticated;
grant execute on function app.owner_agreement_facts(uuid, uuid) to service_role;
revoke all on function app.owner_agreement_facts_0053(uuid, uuid) from public, anon, authenticated;
grant execute on function app.owner_agreement_facts_0053(uuid, uuid) to service_role;

-- The document a person signed (an investment or staff agreement, or a PDF an Admin sent): its signed copy is the document
-- itself followed by the signature page and the record, so "Signed copy" in the portals opens the whole agreement.
create or replace function public.server_sign_request_document(p_id uuid) returns jsonb
language sql stable security definer set search_path = public, app as $$
  select jsonb_build_object('bucket', d.storage_bucket, 'path', d.storage_path, 'sha256', d.sha256)
    from sign_requests r join documents d on d.id = r.document_id
   where r.id = p_id
$$;
revoke all on function public.server_sign_request_document(uuid) from public, anon, authenticated;
grant execute on function public.server_sign_request_document(uuid) to service_role;

-- ---------------------------------------------------------------- 6. the publisher's PDFs, unchanged
-- The owner's rule (October 23, 2026): the forms look exactly as ServiceOntario publishes them; only their empty text
-- boxes are filled (web/src/features/official-forms/pdf-update.ts writes the values as an incremental update after the
-- publisher's last byte; checkboxes, drop-downs and signatures are done by hand at the counter, in ink). The stored
-- templates were the publisher's PDFs opened (decrypted, the Adobe XFA part removed, saved again), and the Adobe dynamic
-- form ON00453 a laid-out copy with the values printed on it. Each publisher's download is registered here with its
-- field list and mapping; app.official_templates_use_originals makes it the current template of its form once the
-- forms-fetch workflow has stored it (forms/templates/<code>/official-<sha>.pdf in the documents bucket; the workflow
-- calls it after storing). Until then the four fillable forms are filled from the stored copies the same way (only
-- their text boxes), and the laid-out copy of ON00453 is no longer used: owners get its data sheet.
create table if not exists official_form_originals (
  id          uuid not null default gen_random_uuid() unique,   -- the audit log's key
  form_code   text primary key,
  from_sha256 text not null,          -- the stored template it replaces
  sha256      text not null,          -- the publisher's download
  file_key    text not null,
  page_count  integer,
  kind        text not null default 'acroform',
  field_names jsonb not null,
  field_map   jsonb not null,
  notes       text,
  used_at     timestamptz,
  created_at  timestamptz not null default now()
);
comment on table official_form_originals is 'The publisher''s download of each official ServiceOntario form (0120), byte for byte, with its fields and mapping; app.official_templates_use_originals makes it the current template once it is stored.';
alter table official_form_originals enable row level security;
create policy admin_all on official_form_originals for all to authenticated using (app.is_admin()) with check (app.is_admin());
revoke all on official_form_originals from anon, authenticated;
grant select, insert, update, delete on official_form_originals to service_role;
create trigger audit_official_form_originals after insert or update or delete on official_form_originals for each row execute function app.audit_row();

create or replace function app.official_form_original(p_code text, p_from text, p_sha256 text, p_key text, p_pages integer, p_fields jsonb, p_map jsonb, p_notes text) returns void
language sql security definer set search_path = public, app as $$
  insert into official_form_originals (form_code, from_sha256, sha256, file_key, page_count, field_names, field_map, notes)
  values (p_code, p_from, p_sha256, p_key, p_pages, p_fields, p_map, p_notes)
  on conflict (form_code) do update set from_sha256 = excluded.from_sha256, sha256 = excluded.sha256, file_key = excluded.file_key, page_count = excluded.page_count,
    field_names = excluded.field_names, field_map = excluded.field_map, notes = excluded.notes
$$;
revoke all on function app.official_form_original(text, text, text, text, integer, jsonb, jsonb, text) from public, anon, authenticated;
grant execute on function app.official_form_original(text, text, text, text, integer, jsonb, jsonb, text) to service_role;

-- Whether a file is in a storage bucket (Supabase storage; false where there is none, as in the tests).
create or replace function app.storage_has(p_bucket text, p_key text) returns boolean
language plpgsql stable security definer set search_path = public, app as $$
declare v boolean := false;
begin
  if to_regclass('storage.objects') is null then return false; end if;
  execute 'select exists (select 1 from storage.objects where bucket_id = $1 and name = $2)' into v using p_bucket, p_key;
  return v;
end $$;
revoke all on function app.storage_has(text, text) from public, anon, authenticated;
grant execute on function app.storage_has(text, text) to service_role;

-- The current template of each form becomes the publisher's download where it is stored (p_force: without looking in
-- the bucket, for a stack whose files are elsewhere). The template keeps its id, its fills and an Admin's own mapping;
-- one with no mapping of an Admin's gets the download's. A template that changes kind (the laid-out ON00453) gets the
-- download's mapping and is to be checked again. Open fills of a form in use are filled again. Returns the forms switched.
create or replace function app.official_templates_use_originals(p_force boolean default false) returns text[]
language plpgsql security definer set search_path = public, app as $$
declare
  r official_form_originals;
  t pdf_templates;
  g record;
  out text[] := '{}';
begin
  for r in select * from official_form_originals order by form_code loop
    if not p_force and not app.storage_has('documents', r.file_key) then continue; end if;
    select * into t from pdf_templates where form_code = r.form_code and is_current and sha256 = r.from_sha256 for update;
    if t.id is null then continue; end if;
    update pdf_templates set file_key = r.file_key, sha256 = r.sha256, page_count = r.page_count, kind = r.kind, field_names = r.field_names,
           field_map = case when t.mapped_by is null or t.kind <> r.kind then r.field_map else t.field_map end,
           notes = case when t.mapped_by is null or t.kind <> r.kind then r.notes else t.notes end,
           mapped_by = case when t.kind <> r.kind then null else t.mapped_by end,
           mapped_at = case when t.mapped_by is null or t.kind <> r.kind then now() else t.mapped_at end,
           verified = t.verified and t.kind = r.kind,
           verified_by = case when t.verified and t.kind = r.kind then t.verified_by end,
           verified_at = case when t.verified and t.kind = r.kind then t.verified_at end
     where id = t.id;
    update official_form_originals set used_at = now() where form_code = r.form_code;
    out := out || r.form_code;
    if t.verified and t.kind = r.kind then
      for g in select f.vehicle_id from government_form_fills f where f.form_code = r.form_code and f.superseded_at is null and f.status not in ('signed', 'filed') loop
        perform app.fill_government_form(g.vehicle_id, r.form_code, null);
      end loop;
    end if;
  end loop;
  return out;
end $$;
revoke all on function app.official_templates_use_originals(boolean) from public, anon, authenticated;
grant execute on function app.official_templates_use_originals(boolean) to service_role;

-- The laid-out copy of ON00453 printed the values over a copy of the form: no longer used for owners (its data sheet
-- until the publisher's download is stored).
update pdf_templates set verified = false, verified_by = null, verified_at = null,
       notes = coalesce(notes || ' ', '') || 'Retired (0120): a laid-out copy is not the publisher''s PDF; the download replaces it once the forms-fetch workflow stores it.'
 where kind = 'overlay' and is_current and form_code in ('SR-LV-006', 'SR-LV-012', 'ON00453', '013-0169', '013-1155');

